terms.medium_def:
A location near Diblathaim only mentioned at Ezk.39.11; 
only referred to as Travelers_Valley (עָבַר גַּיְא). §
Combined with gay (גַּיְא "Valley" H1516O)

A man living at the time of the Patriarchs, first mentioned at Gen.10.21; 
referred to as Eber (עֵ֫בֶר), or Eber (Ἐβέρ); 
a son of Shelah; 
father of Peleg and Joktan.

A man from the tribe of Gad living at the time of Divided Monarchy, only mentioned at 1Ch.5.13; 
only referred to as Eber (עֵ֫בֶר); 
son of Abihail; 
a brother of Michael, Meshullam, Sheba, Jorai, Jacan and Zia.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.12; 
only referred to as Eber (עֵ֫בֶר); 
son of Elpaal; 
a brother of Misham, Shemed, Beriah, Shema, Zebadiah, Meshullam, Hizki, Heber, Ishmerai, Izliah and Jobab.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.22; 
only referred to as Eber (עֵ֫בֶר); 
son of Shashak; 
a brother of Ishpan, Eliel, Abdon, Zichri, Hanan, Hananiah, Elam, Anthothijah, Iphdeiah and Penuel.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.24.27; 
only referred to as Ibri (עִבְרִי); 
son of Jaaziah; 
a brother of Beno, Shoham and Zaccur. § a Merarite Levite of the family of Jaaziah in the time of David

People from Hamath(?) of the Canaanites, first mentioned at Gen.10.18; 
only referred to as Hamathites (חֲמָתִי); 
descended from Canaan along with Sidon, Heth, Jebusites, Amorites, Girgashites, Hivites, Arkites, Sinites, Arvadites and Zemarites. § Hamathite , of Hamath
one of the families descended from Canaan

A man living at the time of Exile and Return, only mentioned at Neh.3.10; 
only referred to as Harumaph (חֲרוּמַף); 
father of Jedaiah. § father of Jedaiah, one of the builders of the wall in Nehemiah's time

A location in Judah Tribe near Tekoa only mentioned at 1Ch.4.12; 
referred to as Ir-nahash (עִיר נָחָשׁ), or Ir-nahash (NIV= Ir Nahash) (=Alt tag) (עִיר נָחָשׁ); 
founded by Tehinnah - perhaps a person, the son of Tehinnah. §#A man of the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.4.12; 
son of: Tehinnah (H8468)

A man from the tribe of Judah living at the time of Egypt and Wilderness, first mentioned at Gen.38.3; 
only referred to as Er (עֵר); 
son of Judah and Bath-shua; 
a brother of Onan and Shelah; 
half-brother of: Perez and Zerah; 
husband of Tamar.

A man from the tribe of Gad living at the time of Egypt and Wilderness, first mentioned at Gen.46.16; 
referred to as Eri (עֵרִי), or Erite (עֵרִי); 
son of Gad; 
a brother of Ziphion, Haggi, Shuni, Ezbon, Arod and Areli. § son of Gad and progenitor of the family of Erites

A man living at the time of United Monarchy, first mentioned at 2Sa.21.19; 
referred to as Jaare-oregim (יַעֲרֵי אֹרְגִים), or Jair (=Qere. Ketiv= Jaur) (יָעִיר); 
father of Elhanan.

A man from the tribe of Judah living at the time of Egypt and Wilderness, only mentioned at 1Ch.4.21; 
only referred to as Er (עֵר); 
son of Shelah; 
a brother of Laadah, Jokim, Joash and Saraph; 
father or founder of Lecah.

A man from the tribe of Gad living at the time of Egypt and Wilderness, first mentioned at Gen.46.16; 
referred to as Eri (עֵרִי), or Erite (עֵרִי); 
son of Gad; 
a brother of Ziphion, Haggi, Shuni, Ezbon, Arod and Areli. § Erites, of Eri "watchful"
descendants of Eri, the son of Gad

A man from the tribe of Ephraim living at the time of Egypt and Wilderness, only mentioned at Num.26.36; 
referred to as Eran (עֵרָן), or Eranite (עֵרָנִי); 
son of Shuthelah; 
a brother of Bered. § the eldest son of Ephraim

A man from the tribe of Ephraim living at the time of Egypt and Wilderness, only mentioned at Num.26.36; 
referred to as Eran (עֵרָן), or Eranite (עֵרָנִי); 
son of Shuthelah; 
a brother of Bered. § Eranites, of Eran "watcher"
the descendants of Eran, the son of Ephraim

People from Aph(?) from the tribe of Judah, first mentioned at 1Ch.2.30; 
only referred to as Appaim (אַפַּיִם); 
descended from Nadab along with Seled; 
progenitors of Ishi. § a son of Nadab
